select.if:
select shareholders_code as shareholdersCode,'PSN' as shareholdersType, hole_share_amount as holeShareAmount,shareholding_proportion as shareholdingProportion,dj_status as djStatus,null as stateOwned, identify_type as identifyType,identify_number as identifyNumber,domestic_or_foreign as domesticOrForeign,name,status from bus_rel_psn where is_shareholder = '1' and DELFLAG_ = '1'
and shareholders_code = #{shareholdersCode}
and name_ like concat(concat('%',#{name_}),'%')
and domestic_or_foreign like #{domesticOrForeign}
and status like #{status}

select shareholders_code as shareholdersCode,'ORG' as shareholdersType,hole_share_amount as holeShareAmount,
shareholding_proportion as shareholdingProportion,dj_status as djStatus,domestic_or_foreign as
domesticOrForeign,
org_name as name_,state_owned as stateOwned,unisc_code as identifyNumber,identify_type as
identifyType,status
from bus_rel_org
where is_shareholder = '1' and DELFLAG_ = '1'

    and shareholders_code = #{shareholdersCode}


    and org_name like concat(concat('%',#{name_}),'%')


    and domestic_or_foreign like #{domesticOrForeign}


    and state_owned = #{stateOwned}


    and status like #{status}

mapper.insert:
insert into bus_gd_file_data (shareholders_code,name_,shareholders_type,domestic_or_foreign,identify_type,identify_number, dj_status,hole_share_amount,shareholding_proportion,status,status_comment,batch_number,state_owned) select * from (
select shareholders_code ,name_,'PSN' as shareholders_type,domestic_or_foreign,identify_type,identify_number,dj_status, hole_share_amount,shareholding_proportion,status,status_comment,#{batchNumber} as batch_number,null as state_owned from bus_rel_psn where is_shareholder = '1' and DELFLAG_ = '1'
and shareholders_code = #{shareholdersCode}
and name_ like concat(concat('%',#{name_}),'%')
and domestic_or_foreign like #{domesticOrForeign}
and status like #{status}
union ALL
select shareholders_code,org_name as name_,'ORG' as shareholders_type,domestic_or_foreign,identify_type,unisc_code as identify_number, dj_status,hole_share_amount,shareholding_proportion,status,status_comment,#{batchNumber} as batch_number,state_owned from bus_rel_org where is_shareholder = '1' and DELFLAG_ = '1'
and shareholders_code = #{shareholdersCode}
and org_name like concat(concat('%',#{name_}),'%')
and domestic_or_foreign like #{domesticOrForeign}
and state_owned = #{stateOwned}
and status like #{status}
) as resource
